def fixed(wb):
    """Stable document properties (openpyxl stamps the current time)."""
    t = datetime.datetime(2026, 1, 1)
    wb.properties.created = t
    wb.properties.modified = t
    wb.properties.creator = "Rusuite"
    wb.properties.lastModifiedBy = "Rusuite"


def build():
    wb = Workbook()
    fixed(wb)
    data = wb.active
    data.title = "Data"
    for row in DATA:
        data.append(row)
    for r in range(2, len(DATA) + 1):
        data.cell(r, 1).number_format = "m/d/yyyy"
    pivot = wb.create_sheet("Pivot")
    for ref, v, fmt, indent in CELLS:
        pivot[ref] = v
        if fmt:
            pivot[ref].number_format = fmt
        if indent:
            pivot[ref].alignment = Alignment(indent=indent)
    chart = BarChart()
    chart.type = "col"
    chart.grouping = "clustered"
    chart.add_data(Reference(pivot, min_col=2, min_row=3, max_row=12), titles_from_data=True)
    chart.set_categories(Reference(pivot, min_col=1, min_row=4, max_row=12))
    chart.pivotSource = PivotSource(name="[provisional-pivot-c3.xlsx]Pivot!PivotTable1", fmtId=0)
    chart.pivotFormats = [PivotFormat(idx=0)]
    pivot.add_chart(chart, "A31")
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
CT = "application/vnd.openxmlformats-officedocument.spreadsheetml."


def rels(*items):
    body = "".join(f'<Relationship Id="{i}" Type="{REL}/{t}" Target="{target}"/>' for i, t, target in items)
    return (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        f"{body}</Relationships>"
    )


def add_pivot(data):
    """Adds the pivot parts openpyxl cannot write."""
    src = zipfile.ZipFile(io.BytesIO(data))
    names = set(src.namelist())
    sheet_rels = "xl/worksheets/_rels/sheet2.xml.rels"
    table_rels = "".join(
        f'<Relationship Id="rIdPt{n}" Type="{REL}/pivotTable" Target="../pivotTables/pivotTable{n}.xml"/>'
        for n in (1, 2, 3)
    )
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
        for info in src.infolist():
            body = src.read(info.filename)
            if info.filename == "[Content_Types].xml":
                extra = (
                    '<Override PartName="/xl/pivotCache/pivotCacheDefinition1.xml" '
                    f'ContentType="{CT}pivotCacheDefinition+xml"/>'
                    '<Override PartName="/xl/pivotCache/pivotCacheRecords1.xml" '
                    f'ContentType="{CT}pivotCacheRecords+xml"/>'
                ) + "".join(
                    f'<Override PartName="/xl/pivotTables/pivotTable{n}.xml" ContentType="{CT}pivotTable+xml"/>'
                    for n in (1, 2, 3)
                )
                body = body.replace(b"</Types>", (extra + "</Types>").encode())
            elif info.filename == "xl/_rels/workbook.xml.rels":
                body = body.replace(
                    b"</Relationships>",
                    (
                        f'<Relationship Id="rIdPc1" Type="{REL}/pivotCacheDefinition" '
                        'Target="pivotCache/pivotCacheDefinition1.xml"/></Relationships>'
                    ).encode(),
                )
            elif info.filename == "xl/workbook.xml":
                body = body.replace(
                    b"</workbook>",
                    (
                        f'<pivotCaches><pivotCache xmlns:r="{REL}" cacheId="1" '
                        'r:id="rIdPc1"/></pivotCaches></workbook>'
                    ).encode(),
                )
            elif info.filename == sheet_rels:
                body = body.replace(b"</Relationships>", (table_rels + "</Relationships>").encode())
            info.date_time = (2026, 1, 1, 0, 0, 0)
            z.writestr(info, body)
        added = [
            ("xl/pivotCache/pivotCacheDefinition1.xml", DEFINITION),
            ("xl/pivotCache/_rels/pivotCacheDefinition1.xml.rels", rels(("rId1", "pivotCacheRecords", "pivotCacheRecords1.xml"))),
            ("xl/pivotCache/pivotCacheRecords1.xml", RECORDS),
        ]
        if sheet_rels not in names:
            added.append((sheet_rels, rels(*[(f"rIdPt{n}", "pivotTable", f"../pivotTables/pivotTable{n}.xml") for n in (1, 2, 3)])))
        for n, table in enumerate(TABLES, 1):
            added.append((f"xl/pivotTables/pivotTable{n}.xml", table))
            added.append(
                (
                    f"xl/pivotTables/_rels/pivotTable{n}.xml.rels",
                    rels(("rId1", "pivotCacheDefinition", "../pivotCache/pivotCacheDefinition1.xml")),
                )
            )
        for name, text in added:
            info = zipfile.ZipInfo(name, date_time=(2026, 1, 1, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            z.writestr(info, text.encode())
    return out.getvalue()


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else "testdata/xlsx"
    with open(f"{out}/provisional-pivot-c3.xlsx", "wb") as f:
        f.write(add_pivot(build()))


if __name__ == "__main__":
    main()
